@SpringBootTest(properties={"testhub.registration.enabled=true","testhub.bootstrap.demo-enabled=false"})
@AutoConfigureMockMvc @ActiveProfiles(resolver=FunctionalDatabaseProfile.class) @DirtiesContext
class ApiDebugHistorySyncFlowTests {
 @TempDir static Path directory;
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){if(FunctionalDatabaseProfile.mysql())FunctionalDatabaseProfile.configure(r,directory,"debug-history-sync-fixture");else{r.add("testhub.desktop.data-directory",directory::toString);r.add("spring.datasource.url",()->"jdbc:h2:file:"+directory.resolve("workspace")+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_ON_EXIT=FALSE");r.add("spring.datasource.username",()->"sa");r.add("spring.datasource.password",()->"debug-history-sync-fixture");}}
 @Autowired ApiDebugService debug; @Autowired RegistrationService registration; @Autowired AccessService access; @Autowired ApiDebugHistorySyncService sync; @Autowired ApiDebugHistoryRepository history; @Autowired ApiReplayTemplateSanitizer sanitizer; @Autowired SecretCipher cipher; @Autowired JdbcClient jdbc; @Autowired ObjectMapper json; @Autowired MockMvc mvc; @Autowired PlatformTransactionManager transactions;
 record Fixture(PlatformUserPrincipal actor,String project){}
 Fixture fixture(){String account="debug-sync-"+UUID.randomUUID();var actor=new PlatformUserPrincipal(registration.register(account,account+"@example.test","调试同步验收","Debug-fixture-2026!"));var c=access.context(actor);return new Fixture(actor,c.projects().get(c.organizations().getFirst().id()).getFirst().id());}
 String identifier(){return com.github.f4b6a3.ulid.UlidCreator.getUlid().toString();}
 JsonNode raw(String protocol)throws Exception{
  var request=json.createObjectNode();if(protocol.equals("GRPC")){request.put("endpoint","example.test:443").put("service","owned.Echo").put("method","Unary").put("requestJson","{\"password\":\"body-private-marker\",\"text\":\"safe\"}").put("descriptorId",identifier());request.putArray("metadata").addObject().put("key","authorization").put("value","Bearer auth-private-marker");}
  else{request.put("url","https://account-private:pass-private@example.test/private-path?token=query-private-marker&x=visible#private-fragment");request.putArray("headers").addObject().put("name","Cookie").put("value","session=cookie-private-marker");if(!protocol.equals("WEBSOCKET")){request.put("name","隔离请求").put("method","POST").put("body","{\"password\":\"body-private-marker\",\"echo\":\"auth-private-marker\",\"safe\":\"kept\"}");var p=request.putObject("protocol");p.put("type",protocol).put("variables","{\"token\":\"variable-private-marker\"}").put("query",protocol.equals("GRAPHQL")?"mutation { login(password: \"graphql-private\") }":"").put("envelope",protocol.equals("SOAP")?"<password>xml-private</password>":"");}
   else{request.putArray("subscriptions").add("{\"token\":\"subscription-private\",\"topic\":\"safe\"}");request.putObject("reconnect").put("enabled",true).put("maxAttempts",3).put("delayMs",1000);request.putArray("subprotocols").add("owned");}}
  request.put("timeoutMs",1000).put("environmentCode","dev");if(protocol.equals("WEBSOCKET"))request.remove("timeoutMs");request.putObject("auth").put("type","BEARER").put("token","auth-private-marker").put("username","").put("password","").put("key","").put("value","");var result=json.createObjectNode().put("protocol",protocol);result.set("request",request);return result;
 }
 String insert(Fixture f,String protocol)throws Exception{String id=identifier();history.insert(new ApiDebugHistory(id,access.context(f.actor()).organizations().getFirst().id(),f.project(),protocol.equals("GRPC")?"GRPC":"POST",protocol,"https://user:pass@example.test/private-path?token=private-query#private-fragment",200,12,34,"COMPLETED","private-error",cipher.encrypt(raw(protocol).toString()),f.actor().userId(),Instant.parse("2026-10-20T01:00:00Z")));return f.project()+"."+id;}
 ApiDebugHistorySyncService.Inventory inventory(Fixture f,String mode){return sync.inventory(f.actor(),f.project(),f.actor().userId(),mode);}
 ApiDebugHistorySyncService.Item item(Fixture f,String mode,String key){return sync.read(f.actor(),f.project(),f.actor().userId(),mode,key);}
 ApiDebugHistorySyncService.Request request(Fixture target,String mode,ApiDebugHistorySyncService.Item... items){return new ApiDebugHistorySyncService.Request(UUID.randomUUID().toString(),target.actor().userId(),inventory(target,mode).revision(),List.of(items));}
 void copy(Fixture s,Fixture t,String mode,String key){sync.apply(t.actor(),t.project(),mode,request(t,mode,item(s,mode,key)));}
 long count(Fixture f,String table){return jdbc.sql("SELECT COUNT(*) FROM "+table+" WHERE project_id=:p").param("p",f.project()).query(Long.class).single();}
 @Test void historySummaryCopiesWithoutPayloadCredentialsPathOrExecutionSideEffects()throws Exception{var s=fixture();var t=fixture();String key=insert(s,"HTTP");var value=item(s,"history",key);String encoded=new String(sync.encoded(value));for(String privateText:List.of("private-path","private-query","private-fragment","private-error","auth-private-marker","body-private-marker","user:pass"))assertFalse(encoded.contains(privateText),privateText);var request=request(t,"history",value);var receipt=sync.apply(t.actor(),t.project(),"history",request);assertEquals(receipt,sync.apply(t.actor(),t.project(),"history",request));assertEquals(value,item(t,"history",key));assertEquals(0,count(t,"api_debug_history"));assertEquals(1,count(t,"api_debug_sync_archive"));assertEquals("https://example.test/…",value.payload().path("target").asText());assertEquals(34,value.payload().path("responseSize").asInt());assertEquals("2026-10-20T01:00:00Z",value.payload().path("createdAt").asText());assertEquals(0,count(t,"api_automation_execution"));}
 @Test void redactedTemplatesCoverAllProtocolsKeepNativeCiphertextAndEncryptCopies()throws Exception{for(String protocol:List.of("HTTP","GRAPHQL","SOAP","WEBSOCKET","GRPC")){var s=fixture();var t=fixture();String key=insert(s,protocol),before=history.findRecent(s.project(),1).getFirst().replayDraft();copy(s,t,"history",key);var draft=item(s,"replay-drafts",key);String serialized=draft.payload().toString();for(String marker:List.of("auth-private-marker","body-private-marker","query-private-marker","cookie-private-marker","variable-private-marker","graphql-private","xml-private","subscription-private","account-private","pass-private"))assertFalse(serialized.contains(marker),protocol+":"+marker);assertTrue(draft.payload().path("notices").toString().contains("MANUAL_REVIEW"));copy(s,t,"replay-drafts",key);assertEquals(draft,item(t,"replay-drafts",key));String encrypted=jdbc.sql("SELECT payload_ciphertext FROM api_debug_sync_archive WHERE project_id=:p AND sync_kind='replay-drafts'").param("p",t.project()).query(String.class).single();assertTrue(encrypted.startsWith("v2:"));assertFalse(encrypted.contains("safe"));assertEquals(before,history.findRecent(s.project(),1).getFirst().replayDraft());assertTrue(cipher.decrypt(before).contains("auth-private-marker"));assertEquals(0,count(t,"api_debug_history"));}}
 @Test void templateRequiresMatchingHistoryAndCannotBeUsedToRewriteOriginals()throws Exception{var s=fixture();var t=fixture();String key=insert(s,"HTTP");var draft=item(s,"replay-drafts",key);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),"replay-drafts",request(t,"replay-drafts",draft)));assertEquals(0,count(t,"api_debug_sync_archive"));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.apply(s.actor(),s.project(),"history",request(s,"history",item(s,"history",key))));copy(s,t,"history",key);copy(s,t,"replay-drafts",key);jdbc.sql("DELETE FROM api_debug_sync_archive WHERE project_id=:p AND sync_kind='history'").param("p",t.project()).update();assertThrows(org.springframework.web.server.ResponseStatusException.class,()->item(t,"replay-drafts",key));}
 @Test void receiptCannotRecreateDeletedRowsAndUuidCannotChangeBody()throws Exception{var s=fixture();var t=fixture();String key=insert(s,"HTTP");var request=request(t,"history",item(s,"history",key));sync.apply(t.actor(),t.project(),"history",request);var changed=new ApiDebugHistorySyncService.Request(request.requestKey(),request.expectedUserId(),"0".repeat(64),request.items());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),"history",changed));jdbc.sql("DELETE FROM api_debug_sync_archive WHERE project_id=:p").param("p",t.project()).update();assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),"history",request));assertEquals(0,count(t,"api_debug_sync_archive"));}
 @Test void actorProjectViewerCsrfAndStrictBodyLimitsAreEnforced()throws Exception{var s=fixture();var t=fixture();String key=insert(s,"HTTP"),route="/api/v1/projects/"+t.project()+"/api-debug/history/archive/sync";var request=request(t,"history",item(s,"history",key));mvc.perform(post(route).with(user(t.actor())).contentType("application/json").content(json.writeValueAsBytes(request))).andExpect(status().isForbidden());mvc.perform(get(route).with(user(s.actor())).param("expectedUserId",s.actor().userId())).andExpect(status().isForbidden());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.inventory(t.actor(),t.project(),s.actor().userId(),"history"));jdbc.sql("UPDATE membership SET role_code='VIEWER' WHERE user_id=:u").param("u",t.actor().userId()).update();mvc.perform(get(route).with(user(t.actor())).param("expectedUserId",t.actor().userId())).andExpect(status().isForbidden());mvc.perform(post(route).with(user(t.actor())).with(csrf()).contentType("application/json").content(json.writeValueAsBytes(request))).andExpect(status().isForbidden());var extra=(com.fasterxml.jackson.databind.node.ObjectNode)json.valueToTree(request);extra.put("unsupported",true);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.decode(json.writeValueAsBytes(extra)));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.decode("null".getBytes()));assertEquals(413,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.decode(new byte[ApiDebugHistorySyncService.MAX_BYTES+1])).getStatusCode().value());}
 @Test void transactionsRollBackArchiveAndReceiptAndCipherCorruptionPausesRead()throws Exception{var s=fixture();var t=fixture();String key=insert(s,"HTTP");new TransactionTemplate(transactions).executeWithoutResult(tx->{copy(s,t,"history",key);tx.setRollbackOnly();});assertEquals(0,count(t,"api_debug_sync_archive"));assertEquals(0,count(t,"api_debug_sync_receipt"));copy(s,t,"history",key);jdbc.sql("UPDATE api_debug_sync_archive SET payload_ciphertext='bad' WHERE project_id=:p").param("p",t.project()).update();assertThrows(org.springframework.web.server.ResponseStatusException.class,()->item(t,"history",key));assertEquals(1,count(t,"api_debug_sync_archive"));}
 @Test void migratedOriginIsRetainedAndDuplicateSourceIsNeverSilentlyCollapsed()throws Exception{var s=fixture();var t=fixture();String key=insert(s,"HTTP");var row=history.findRecent(s.project(),1).getFirst();history.insert(new ApiDebugHistory(identifier(),access.context(t.actor()).organizations().getFirst().id(),t.project(),row.method(),row.protocol(),row.requestUrl(),row.responseStatus(),row.durationMs(),row.responseSize(),row.result(),row.errorMessage(),cipher.encrypt(cipher.decrypt(row.replayDraft())),t.actor().userId(),row.createdAt(),s.project(),row.id()));assertEquals(key,inventory(t,"history").entries().getFirst().key());assertFalse(inventory(t,"history").entries().getFirst().nativeRecord());assertEquals(item(s,"history",key),item(t,"history",key));}
 @Test void projectSecretAndOpaquePayloadsAreRemovedWhileVariablesStayTemplates()throws Exception{var f=fixture();var raw=raw("HTTP");((com.fasterxml.jackson.databind.node.ObjectNode)raw.path("request")).put("body","unstructured project-private-value").put("name","project-private-value");var safe=sanitizer.sanitize(raw,Set.of("project-private-value"));assertFalse(safe.template().toString().contains("project-private-value"));assertTrue(safe.template().path("request").path("body").asText().contains("SYNC_REVIEW"));assertEquals(safe.template(),sanitizer.sanitize(safe.template(),Set.of()).template());var deep=json.createObjectNode();var cursor=deep;for(int n=0;n<40;n++)cursor=cursor.putObject("next");((com.fasterxml.jackson.databind.node.ObjectNode)raw.path("request")).put("body",deep.toString());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sanitizer.sanitize(raw,Set.of()));}
 @Test void invalidSummaryTypesImmutableChangesAndBatchLimitsRollBack()throws Exception{var s=fixture();var t=fixture();String key=insert(s,"HTTP");var value=item(s,"history",key);for(String field:List.of("durationMs","responseSize","responseStatus")){var payload=value.payload().deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)payload).put(field,"200");String hash=io.testhub.platform.functional.FunctionalTransferFiles.sha256(sync.encoded(payload));var bad=new ApiDebugHistorySyncService.Item(key,hash,hash,payload);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),"history",request(t,"history",bad)));}copy(s,t,"history",key);var changed=value.payload().deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)changed).put("durationMs",99);String hash=io.testhub.platform.functional.FunctionalTransferFiles.sha256(sync.encoded(changed));var bad=new ApiDebugHistorySyncService.Item(key,hash,hash,changed);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),"history",request(t,"history",bad)));assertEquals(value,item(t,"history",key));var batch=new ApiDebugHistorySyncService.Request(UUID.randomUUID().toString(),t.actor().userId(),inventory(t,"history").revision(),Collections.nCopies(21,value));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sync.apply(t.actor(),t.project(),"history",batch));assertEquals(1,count(t,"api_debug_sync_archive"));}
 @Test void nativeCapacityAndAggregateStoredBytesFailBeforeTruncation()throws Exception{var f=fixture();String key=insert(f,"HTTP");var row=history.findRecent(f.project(),1).getFirst();jdbc.sql("UPDATE api_debug_history SET replay_draft_ciphertext=:v WHERE project_id=:p").param("v","x".repeat(8*1024*1024+1)).param("p",f.project()).update();assertThrows(org.springframework.web.server.ResponseStatusException.class,()->inventory(f,"history"));jdbc.sql("UPDATE api_debug_history SET replay_draft_ciphertext=:v WHERE project_id=:p").param("v",row.replayDraft()).param("p",f.project()).update();for(int n=0;n<1000;n++)history.insert(new ApiDebugHistory(identifier(),row.organizationId(),f.project(),"GET","HTTP","https://example.test/",200,0,0,"COMPLETED",null,null,f.actor().userId(),row.createdAt()));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->inventory(f,"history"));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->item(f,"history",key));}
 @Test void nestedEncodedBodiesAndIpv6SummariesAreHandledWithoutStackOverflow()throws Exception{var f=fixture();String key=insert(f,"HTTP");jdbc.sql("UPDATE api_debug_history SET request_url='https://[::1]:9000/private?token=private' WHERE project_id=:p").param("p",f.project()).update();assertEquals("https://[::1]:9000/…",item(f,"history",key).payload().path("target").asText());var raw=raw("HTTP");String encoded="{}";for(int n=0;n<10;n++)encoded=json.createObjectNode().put("body",encoded).toString();var nested=json.createObjectNode();var cursor=nested;for(int n=0;n<25;n++)cursor=cursor.putObject("next");cursor.put("body",encoded);encoded=nested.toString();((com.fasterxml.jackson.databind.node.ObjectNode)raw.path("request")).put("body",encoded);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sanitizer.sanitize(raw,Set.of()));}

 @Test void repeatedCookieValuesProjectKeysAndNullAuthAreSafe()throws Exception{var f=fixture();String key=insert(f,"HTTP");jdbc.sql("INSERT INTO project_parameter(id,organization_id,project_id,environment_code,parameter_key,parameter_value,secret,updated_by) VALUES(:id,:o,:p,'dev','PRIVATE',:v,TRUE,:u)").param("id",identifier()).param("o",access.context(f.actor()).organizations().getFirst().id()).param("p",f.project()).param("v",cipher.encrypt("project-key-private-marker")).param("u",f.actor().userId()).update();var raw=raw("HTTP");((com.fasterxml.jackson.databind.node.ObjectNode)raw.path("request")).put("body","{\"echo\":\"cookie-private-marker\",\"keyEcho\":\"project-key-private-marker\",\"passwords\":[\"repeated-private-marker\"],\"repeated\":\"repeated-private-marker\"}");((com.fasterxml.jackson.databind.node.ObjectNode)raw.path("request").path("auth")).putNull("password");jdbc.sql("UPDATE api_debug_history SET replay_draft_ciphertext=:v WHERE project_id=:p").param("v",cipher.encrypt(raw.toString())).param("p",f.project()).update();var safe=item(f,"replay-drafts",key).payload();for(String marker:List.of("cookie-private-marker","project-key-private-marker","repeated-private-marker"))assertFalse(safe.toString().contains(marker));assertTrue(safe.path("template").path("request").path("auth").path("password").isNull());assertEquals(safe.path("template"),sanitizer.sanitize(safe.path("template"),Set.of()).template());((com.fasterxml.jackson.databind.node.ObjectNode)raw.path("request")).put("auth","untyped-private");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->sanitizer.sanitize(raw,Set.of()));}

 @Test void realSavedDraftWithNullableDtoFieldsRemainsIdempotentAndLoadable()throws Exception{var f=fixture();var raw=new ApiDebugService.DebugRequest("POST","https://1.1.1.1/owned?token=real-private-query",List.of(new ApiDebugService.HeaderInput("Cookie","owned=real-private-cookie")),"{\"safe\":\"kept\"}",1000,null,new ApiDebugService.AuthInput("BEARER","real-private-token",null,null,null,null,null),new ApiDebugService.ProtocolInput("HTTP",null,null,null,null,null),"真实草稿");var saved=debug.saveDraft(f.actor(),f.project(),raw);String before=history.findRecent(f.project(),1).getFirst().replayDraft();var value=item(f,"replay-drafts",f.project()+"."+saved.id());assertTrue(value.payload().path("template").path("request").path("protocol").path("variables").isNull());assertTrue(value.payload().path("template").path("request").path("auth").path("password").isNull());assertEquals(value.payload().path("template"),sanitizer.sanitize(value.payload().path("template"),Set.of()).template());assertFalse(value.toString().contains("real-private"));assertEquals(before,history.findRecent(f.project(),1).getFirst().replayDraft());}

}
